def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count overall rates
    opp_c = 0
    my_c = 0
    for (me, opp) in history:
        if opp == 'C':
            opp_c += 1
        if me == 'C':
            my_c += 1
    opp_d = n - opp_c
    opp_rate = opp_c / n

    last_me, last_opp = history[-1]

    # Detect opponent defection streak
    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    # Detect our own defection streak
    my_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_streak_d += 1
        else:
            break

    # Recent window analysis
    w = 10 if n >= 10 else n
    recent_opp_c = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            recent_opp_c += 1

    # Early: cooperate, but retaliate immediately
    if n < 4:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Exploit endgame against extremely cooperative opponents
    if n >= 90 and opp_rate > 0.85:
        return 'D'

    # Opponent almost always cooperates: stay in CC, with rare probe
    if opp_rate >= 0.95:
        if n < 85 and n > 10 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Opponent heavily defects: defect, with rare re-establishment attempts
    if opp_rate < 0.2:
        if opp_streak_d >= 6 and n < 90 and rng.random() < 0.1:
            return 'C'
        return 'D'

    # Opponent just defected
    if last_opp == 'D':
        # If they defected after long CC streak, punish firmly
        if opp_streak_d >= 3:
            return 'D'
        # If we've been punishing a while, consider restoring cooperation
        if my_streak_d >= 2 and recent_opp_c >= 3 and rng.random() < 0.35:
            return 'C'
        # Otherwise retaliate
        return 'D'

    # Opponent just cooperated
    if last_opp == 'C':
        # If opponent is highly cooperative recently, cooperate
        if recent_opp_c >= w - 1:
            return 'C'
        # If opponent is moderate and we've been defecting, restore cooperation
        if my_streak_d >= 2:
            return 'C'
        # Occasional probe against very cooperative opponents
        if opp_rate > 0.75 and n < 80 and rng.random() < 0.03:
            return 'D'
        return 'C'

    return 'C'
